allnew=json.load(open('my6_a.json'))+json.load(open('my6_b.json'))+json.load(open('my6_c.json'))
norm=lambda s: re.sub(r'[^a-z0-9 ]','',s.lower()).strip()
old=set(norm(p['text']) for p in practice())
for f in ['my_sents_all.json','my_sents3_all.json','my_sents4_all.json','my_sents5_all.json']:
    d=json.load(open(f))
    if isinstance(d,dict):
        print(f, list(d.keys())[:3]); 
        items=[]
        for k,v in d.items():
            if isinstance(v,list): items+= [x if isinstance(x,str) else x.get('text','') for x in v]
    else:
        items=[x if isinstance(x,str) else (x.get('text') if isinstance(x,dict) else x[0]) for x in d]
    for t in items: old.add(norm(t))
print(len(old))
seen=set(); out=[]
for s in allnew:
    n=norm(s['text'])
    if n in old or n in seen: print('dup',s['text']); continue
    seen.add(n); out.append(s)
print(len(out))
json.dump(out,open('my6_all.json','w'),indent=0)
toks=tokenize([s['text'] for s in out]); print(max(len(t['ids']) for t in toks))

